@Override
protected void attackEntity(net.minecraft.core.entity.Entity target, float distance) {
	if (distance < 2.0f && this.attackTime <= 0) {
		this.attackTime = 20;
		target.hurt(this, {{attackDamage}}, net.minecraft.core.util.helper.DamageType.COMBAT);
	}
}

